#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0 || n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    double a = 0.0;
    double b = (double)n + 1.0;
    int i;
    for (i = 0; i < 60; i++) {
        double c = (a + b) * 0.5;
        double c2 = c * c;
        if (c2 == (double)n) {
            printf("%.6f\n", c);
            return 0;
        }
        if (c2 < (double)n) {
            a = c;
        } else {
            b = c;
        }
    }
    printf("%.6f\n", (a + b) * 0.5);
    return 0;
}
